from lib import *
S = SS('h6')
steps = [
    step("客户端取消在线上是一个 RST_STREAM 帧(错误码 CANCEL):调用 100 ms 后 cancel(),线上客户端到服务端依次是 HEADERS(流 3,没有 grpc-timeout)、DATA、RST_STREAM(错误码 CANCEL),客户端得到 Canceled。deadline 到期的情形不同:HEADERS 里带 grpc-timeout: 99928041n,服务端自己先发出 RST_STREAM(CANCEL),客户端随后也发 RST_STREAM(CANCEL),客户端得到 DeadlineExceeded——超时是两边各自计时,各自结束这条流。", t=tl(S(1)), done=lidx(S(1), '  cancel:客户端得到 Canceled'), mark=lidx(S(1), '  deadline:客户端得到'), b=bars([['cancel:RST_STREAM 帧数', 1, '1(客户端发)'], ['deadline:RST_STREAM 帧数', 2, '2(服务端先发,客户端也发)']], 2.2, done=[0], mark=[1]), kv=KV([['cancel()', '客户端发 RST_STREAM(CANCEL)'], ['deadline 到期', '服务端和客户端各发一个 RST_STREAM(CANCEL)'], ['客户端看到', 'Canceled / DeadlineExceeded']], ['cancel()'])),
    step("50 个调用都超时返回后,服务端还有多少个 handler 在运行:handler 监听 ctx.Done()(watch)的,客户端全部返回时服务端是 0 个;不监听 ctx(睡 500 ms)的,客户端全部返回时服务端还有 50 个在运行,100 ms 后仍是 50 个,等 400 ms 之后降到 0 个。服务端 handler 不看 ctx 的话,客户端取消的请求仍然占用服务端资源直到干完——取消是“通知”,不是“强制停止”。", t=tl(S(2)), done=lidx(S(2), '  ignore  客户端 50 个'), mark=lidx(S(2), '  watch   客户端 50 个'), b=bars([['watch:客户端返回时仍在运行', 0, '0'], ['ignore:客户端返回时仍在运行', 50, '50'], ['ignore:再过 100 ms', 50, '50'], ['ignore:再过 400 ms', 0, '0']], 52, done=[0, 3], mark=[1, 2]), kv=KV([['监听 ctx.Done()', '客户端返回时 handler 已经全停(0 个)'], ['不监听 ctx', '50 个继续跑到睡眠结束'], ['含义', '取消只是通知,handler 要自己检查']], ['含义'])),
    step("流式 RPC 取消:客户端收到 5 条消息后取消,下一次 Recv 立刻返回 code=Canceled(0.1 ms)。服务端这一边:第 5 次 Send(从 0 数起;之前的 0–4 号已经被客户端收到)失败,错误是 rpc error: code = Canceled desc = context canceled,st.Context().Err() 也是 context canceled,200 ms 后还在运行的 handler 是 0 个——流式 handler 一旦在 Send 处检查错误并返回,就会及时退出。忘了检查 Send 的返回值,handler 就会一直发到出错也不停。", t=tl(S(3)), done=lidx(S(3), '服务端:第 5 次 Send 失败'), mark=lidx(S(3), '客户端取消后下一次 Recv'), b=bars([['客户端 Recv 返回耗时 ms', 0.1, '0.1'], ['取消后仍在运行的 handler', 0, '0']], 1, done=[0, 1]), kv=KV([['客户端', '下一次 Recv 立刻返回 Canceled'], ['服务端', 'Send 失败:code = Canceled,ctx.Err() = context canceled'], ['前提', 'handler 检查 Send 的返回值']], ['前提'])),
    step("取消和响应赛跑:handler 固定耗时约 1 ms,客户端在不同延迟后取消,各 400 次。500 µs 后取消:成功 0、Canceled 400;1000 µs:成功 0、Canceled 400;1500 µs:成功 396、Canceled 4;2000 µs:成功 400;4000 µs:成功 400。分界在 1 ms 的 handler 耗时加上约 0.3–0.5 ms 的往返开销之间。如果取消恰好和响应撞上,结果可能是成功也可能是 Canceled——处理结果的代码不能假设“取消了就一定没执行”;服务端可能已经执行完了(见分布式事务系列的幂等)。", t=tl(S(4)), done=lidx(S(4), '客户端 1500 µs'), mark=lidx(S(4), '客户端  500 µs'), b=bars([['500 µs 取消:成功', 0, '0'], ['1000 µs 取消:成功', 0, '0'], ['1500 µs 取消:成功', 396, '396'], ['2000 µs 取消:成功', 400, '400']], 400, mark=[0, 1], done=[2, 3]), kv=KV([['取消早于完成', 'Canceled 400/400'], ['取消晚于完成', '成功 400/400'], ['分界附近', '1500 µs 时 396 成功 + 4 Canceled']], ['分界附近'])),
    step("调用已经完成后再 cancel():等线上安静后测,调用完成后线上的 RST_STREAM 是 0 个;再调用 cancel() 之后仍是 0 个。所以典型写法 ctx, cancel := context.WithTimeout(…); defer cancel() 不会多发任何帧——cancel 只在调用还没结束时才会让连接上多出 RST_STREAM,调用已结束后什么都不做。", t=tl(S(5)), done=lidx(S(5), '调用完成后线上 RST_STREAM'), b=bars([['调用完成后的 RST_STREAM', 0, '0'], ['再 cancel() 之后', 0, '0']], 1, done=[0, 1]), kv=KV([['调用完成后 cancel()', '线上没有任何帧'], ['defer cancel() 的写法', '没有额外开销'], ['未完成时 cancel()', '才会发 RST_STREAM']], ['defer cancel() 的写法'])),
    step("取消沿调用链传到下游(A → B → C,每层都传 ctx 并监听 ctx.Done()):客户端在 101.0 ms 取消,A 在 101.2 ms、B 在 101.2 ms、C 在 101.3 ms 发现自己的 ctx 被取消,距取消分别 0.1、0.2、0.3 ms。本机上三层的取消几乎同时到达(每层转发 RST_STREAM 的开销只有零点几毫秒);网络上每一跳要加上自己的往返延迟。前提仍然是每层把 ctx 传下去(上一篇)。", t=tl(S(6)), done=lidx(S(6), '客户端在 101.0 ms 时取消'), b=bars([['A 距取消 ms', 0.1, '0.1'], ['B 距取消 ms', 0.2, '0.2'], ['C 距取消 ms', 0.3, '0.3']], 0.35, done=[0, 1, 2]), kv=KV([['客户端取消', '101.0 ms'], ['A / B / C 发现取消', '距取消 0.1 / 0.2 / 0.3 ms'], ['前提', '每层传 ctx 并监听 ctx.Done()']], ['前提'])),
]
A = mkarth('h6', 6, 'gRPC,取消,context,RST_STREAM,goroutine,流式,竞态,Go,真实验证,动画演示',
    '实测 gRPC 取消:cancel 是一个 RST_STREAM(CANCEL),deadline 到期两边各发一个;handler 不监听 ctx 就会继续跑完;流式 Send 在取消后失败并带 Canceled;取消与响应赛跑可能成功也可能 Canceled;调用完成后 cancel() 不发帧;取消沿调用链几乎同时传到下游。',
    '客户端取消或超时后,服务端的 goroutine 怎么停?线上是什么帧?流式 RPC 呢?取消刚好撞上响应会怎样?这篇逐项抓包和计数。',
    [('0 对 50', '50 个调用超时返回后,服务端仍在运行的 handler 数:监听 ctx.Done() 与不监听'), ('RST_STREAM(CANCEL)', '客户端 cancel() 在线上的样子;deadline 到期时服务端和客户端各发一个'), ('0 个', '调用完成后再 cancel() 在线上多发的帧')],
    [('线上的取消', '<p>取消就是 RST_STREAM 帧(错误码 CANCEL)。cancel() 由客户端发出;deadline 到期则两边都会计时并各发一个。</p>'),
     ('handler 要自己停', '<p>服务端的 ctx 会被取消,但 handler 不检查就继续跑:50 个不监听 ctx 的 handler 在客户端全部返回时仍在运行,直到睡眠结束。长耗时的 handler 要在阻塞处 select ctx.Done()。</p>'),
     ('流式', '<p>客户端取消后,服务端流的 Send 会失败并返回带 Canceled 的错误;检查 Send 的返回值才能及时退出。</p>'),
     ('竞态', '<p>取消和响应恰好撞上时,结果是成功还是 Canceled 取决于时序:取消不能保证请求没被执行,需要幂等。</p>'),
     ('defer cancel()', '<p>调用结束后再 cancel() 什么帧都不发,所以 defer cancel() 是安全且免费的。</p>'),
     ('沿调用链', '<p>取消通过每一层传递 ctx 一路传到最下游,本机上每跳只要零点几毫秒;前提是每一层都传 ctx(第 5 篇)。</p>')],
    steps,
    [ENV_H + '。第一节用抓包代理看帧;第二节的“正在运行的 handler 数”是服务端自己的原子计数器;第四节每个延迟 400 次、最多 8 个并发;第五节在线上安静 500 ms 之后测;第六节的 ms 数都是同进程里 time.Now 的差,单次测量',
     '没有验证:在真实网络上取消传播的延迟;服务端用 grpc.MaxConcurrentStreams 限制时取消对排队请求的影响;HTTP/2 RST_STREAM 的流控含义(被取消的流上已发送的数据是否还占流控窗口);客户端流和双向流里取消的细节;非 grpc-go 的服务端实现'],
    '取消')
